composite.setup:
SET default_statistics_target = 10000;
CREATE TABLE orders AS
SELECT g AS id,
  (1 + (g::bigint * 7919) % 50000)::int AS customer_id,
  TIMESTAMP '2024-01-01' + (g - 1) * INTERVAL '31.62 seconds' AS created_at,
  (ARRAY['pending', 'paid', 'shipped', 'returned'])[1 + g % 4] AS status,
  round(5 + ((g * 37) % 9500) / 100.0, 2) AS amount
FROM generate_series(1, 1000000) g;
ALTER TABLE orders ADD PRIMARY KEY (id);
VACUUM ANALYZE orders

customers.sql:
SELECT COUNT(*) AS orders, COUNT(DISTINCT customer_id) AS customers,
  COUNT(*) / COUNT(DISTINCT customer_id) AS each
FROM orders;

create.sql:
CREATE INDEX orders_customer_created_idx
  ON orders (customer_id, created_at);
ANALYZE orders;

dayCount.sql:
SELECT COUNT(*) FROM orders
WHERE created_at >= '2024-12-31'
  AND created_at <  '2025-01-01';

reverse.sql:
DROP INDEX orders_customer_created_idx;
CREATE INDEX orders_created_customer_idx
  ON orders (created_at, customer_id);
ANALYZE orders;

skip.sql:
DROP INDEX orders_created_customer_idx;
CREATE INDEX orders_status_created_idx
  ON orders (status, created_at);
ANALYZE orders;

